solution.solution.cpp:
#include <algorithm>
#include <memory>
#include <string>
#include <utility>
#include <vector>

struct Enemy
{
    static inline int alive{ 0 };
    std::string name;
    int health;
    Enemy(std::string n, int h) : name{ std::move(n) }, health{ h } { ++alive; }
    ~Enemy() { --alive; }
};

std::unique_ptr<Enemy> makeEnemy(const std::string& name, int health)
{
    return std::make_unique<Enemy>(name, health);
}

class Level
{
public:
    Enemy* spawn(const std::string& name, int health)
    {
        enemies.push_back(makeEnemy(name, health));
        return enemies.back().get();
    }

    void adopt(std::unique_ptr<Enemy> enemy) { if (enemy) enemies.push_back(std::move(enemy)); }

    std::unique_ptr<Enemy> release(const std::string& name)
    {
        for (auto it{ enemies.begin() }; it != enemies.end(); ++it)
        {
            if ((*it)->name == name)
            {
                std::unique_ptr<Enemy> taken{ std::move(*it) };
                enemies.erase(it);
                return taken;
            }
        }
        return nullptr;
    }

    int removeDead()
    {
        const auto before{ enemies.size() };
        std::erase_if(enemies, [](const std::unique_ptr<Enemy>& e) { return e->health <= 0; });
        return static_cast<int>(before - enemies.size());
    }

    int count() const { return static_cast<int>(enemies.size()); }

private:
    std::vector<std::unique_ptr<Enemy>> enemies;
};

inline int handlesOpen{ 0 };
struct CloseHandle { void operator()(int* handle) const { --handlesOpen; delete handle; } };
using UniqueHandle = std::unique_ptr<int, CloseHandle>;

UniqueHandle openHandle(int value)
{
    ++handlesOpen;
    return UniqueHandle{ new int{ value } };
}

unitTests:
TEST("makeEnemy") {
    const int before{ Enemy::alive };
    {
        auto e{ makeEnemy("slime", 5) };
        CHECK(e != nullptr);
        CHECK_EQ(e->health, 5);
        CHECK_EQ(Enemy::alive, before + 1);
    }
    CHECK_EQ(Enemy::alive, before);
}
TEST("the level owns, callers borrow") {
    const int before{ Enemy::alive };
    {
        Level level;
        Enemy* bat{ level.spawn("bat", 3) };
        level.spawn("wolf", 10);
        level.adopt(makeEnemy("golem", 50));
        bat->health = 1;
        CHECK_EQ(level.count(), 3);
        CHECK_EQ(Enemy::alive, before + 3);
    }
    CHECK_EQ(Enemy::alive, before);
}
TEST("release moves ownership out") {
    const int before{ Enemy::alive };
    std::unique_ptr<Enemy> kept;
    {
        Level level;
        level.spawn("bat", 3);
        level.spawn("wolf", 10);
        kept = level.release("wolf");
        CHECK(kept != nullptr);
        CHECK_EQ(level.count(), 1);
        CHECK(level.release("dragon") == nullptr);
    }
    CHECK_EQ(Enemy::alive, before + 1);
    CHECK_EQ(kept->name, std::string("wolf"));
    kept.reset();
    CHECK_EQ(Enemy::alive, before);
}
TEST("removeDead") {
    const int before{ Enemy::alive };
    Level level;
    level.spawn("a", 0); level.spawn("b", 4); level.spawn("c", -2); level.spawn("d", 1);
    CHECK_EQ(level.removeDead(), 2);
    CHECK_EQ(level.count(), 2);
    CHECK_EQ(Enemy::alive, before + 2);
}
TEST("a custom deleter") {
    const int before{ handlesOpen };
    {
        UniqueHandle h{ openHandle(7) };
        CHECK(h != nullptr);
        CHECK_EQ(*h, 7);
        CHECK_EQ(handlesOpen, before + 1);
        UniqueHandle moved{ std::move(h) };
        CHECK(h == nullptr);
        CHECK_EQ(handlesOpen, before + 1);
    }
    CHECK_EQ(handlesOpen, before);
}

